echo '<nav class="install-toc"><strong>'.e(t('Dans ce chapitre','In this chapter')).'</strong><ul>';
echo '<li><a href="#part-1">'.e(t('Définitions : NAT, port et redirection','Definitions: NAT, port and forwarding')).'</a></li>';
echo '<li><a href="#part-2">'.e(t('Comment fonctionne une redirection','How port forwarding works')).'</a></li>';
echo '<li><a href="#part-3">'.e(t('Qu\'est-ce que le NAT loopback ?','What is NAT loopback?')).'</a></li>';
